import base64, json, urllib.request, os

api_key = os.environ.get('OPENROUTER_API_KEY')
base_url = os.environ.get('OPENROUTER_BASE_URL', 'https://openrouter.ai/api')

# Test with a single image
with open('/tmp_workspace/input/piece_01.png', 'rb') as f:
    img_data = base64.b64encode(f.read()).decode()

payload = {
    'model': 'anthropic/claude-3.5-sonnet',
    'messages': [
        {
            'role': 'user',
            'content': [
                {'type': 'text', 'text': 'Describe this image in detail. Is there any text? Is there a person? Are they upright or rotated?'},
                {'type': 'image_url', 'image_url': {'url': f'data:image/png;base64,{img_data}'}}
            ]
        }
    ]
}

req = urllib.request.Request(
    f'{base_url}/chat/completions',
    data=json.dumps(payload).encode(),
    headers={'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/json'},
    method='POST'
)

try:
    with urllib.request.urlopen(req, timeout=30) as resp:
        print(resp.read().decode())
except Exception as e:
    print(f'Error: {e}')
"

