OUTPUT_DIR = '/tmp_workspace/results'

# Load all pieces
images = {}
arrays = {}
for p in PIECES:
    img = Image.open(os.path.join(INPUT_DIR, p))
    images[p] = img
    arrays[p] = np.array(img)

print("Loaded", len(images), "pieces")

# Edge extraction: for a 200x200 image, edges are the outermost 2 pixels to be robust
# left, right, top, bottom edges (each 200x2 or 2x200)
def get_edges(arr):
    # arr: H x W x C
    left = arr[:, :2, :]
    right = arr[:, -2:, :]
    top = arr[:2, :, :]
    bottom = arr[-2:, :, :]
    return left, right, top, bottom

# For rotated images, we need to know which edge corresponds to which after rotation
# rotate 90 CW: top->right, right->bottom, bottom->left, left->top (but reversed order)
# Actually, let's just compare edges after rotating the candidate back

def rotate_arr(arr, k):
    # k clockwise 90-degree turns
    return np.rot90(arr, k=-k)  # negative = clockwise

# Edge comparison: mean absolute difference
def edge_diff(e1, e2):
    # e1 and e2 should be same shape
    if e1.shape != e2.shape:
        return float('inf')
    return np.mean(np.abs(e1.astype(float) - e2.astype(float)))

# For each piece, compute edges in all 4 orientations
# edges_all[piece][orientation] = (left, right, top, bottom) where orientation 0=original, 1=90CW, 2=180, 3=270CW
edges_all = {}
for p in PIECES:
    edges_all[p] = {}
    for k in range(4):
        rot = rotate_arr(arrays[p], k)
        edges_all[p][k] = get_edges(rot)

# Precompute best matches between pieces
match_right_left = {}
match_bottom_top = {}

for p1 in PIECES:
    match_right_left[p1] = {}
    match_bottom_top[p1] = {}
    for o1 in range(4):
        match_right_left[p1][o1] = {}
        match_bottom_top[p1][o1] = {}
        _, r1, _, b1 = edges_all[p1][o1]
        for p2 in PIECES:
            if p1 == p2:
                continue
            best_rl = (float('inf'), None)
            best_bt = (float('inf'), None)
            for o2 in range(4):
                l2, _, t2, _ = edges_all[p2][o2]
                d_rl = edge_diff(r1, l2)
                if d_rl < best_rl[0]:
                    best_rl = (d_rl, o2)
                d_bt = edge_diff(b1, t2)
                if d_bt < best_bt[0]:
                    best_bt = (d_bt, o2)
            match_right_left[p1][o1][p2] = best_rl
            match_bottom_top[p1][o1][p2] = best_bt

print("Precomputed edge matches")

# Strategy: For each piece, compute its "connectivity score" - how well it can connect to other pieces
# Distractors should have poor connectivity
connectivity = {}
for p in PIECES:
    scores = []
    for o in range(4):
        for p2 in PIECES:
            if p == p2:
                continue
            scores.append(match_right_left[p][o][p2][0])
            scores.append(match_bottom_top[p][o][p2][0])
    # Sort and take the best 8 scores (a piece in 3x3 grid has at most 4 neighbors, but we check both directions)
    scores.sort()
    connectivity[p] = np.mean(scores[:8])

print("\nConnectivity scores (lower = better connected):")
for p in sorted(PIECES, key=lambda x: connectivity[x]):
    print(f"  {p}: {connectivity[p]:.2f}")

# The 6 pieces with worst connectivity are likely distractors
sorted_by_conn = sorted(PIECES, key=lambda x: connectivity[x])
likely_distractors = sorted_by_conn[-6:]
print(f"\nLikely distractors (worst connectivity): {likely_distractors}")

# Now try to arrange the remaining 9 pieces
remaining = [p for p in PIECES if p not in likely_distractors]
print(f"Remaining pieces: {remaining}")

# Try to arrange in 3x3
best_solution = None
best_score = float('inf')

THRESHOLD = 100  # Even more relaxed for the likely correct pieces

subset = remaining
grid = [[None for _ in range(3)] for _ in range(3)]
used = set()

def place(r, c):
    global best_solution, best_score
    if r == 3:
        # Complete grid! Compute total score
        total = 0
        for i in range(3):
            for j in range(3):
                p, o = grid[i][j]
                if j < 2:
                    p2, o2 = grid[i][j+1]
                    d = match_right_left[p][o][p2][0]
                    total += d
                if i < 2:
                    p2, o2 = grid[i+1][j]
                    d = match_bottom_top[p][o][p2][0]
                    total += d
        if total < best_score:
            best_score = total
            best_solution = [row[:] for row in grid]
            print(f"New best score: {total:.2f}")
        return

    # Try each unused piece from subset
    for p in subset:
        if p in used:
            continue
        for o in range(4):
            # Check consistency with left neighbor
            if c > 0:
                p_left, o_left = grid[r][c-1]
                d = match_right_left[p_left][o_left][p][0]
                if d > THRESHOLD:
                    continue
            # Check consistency with top neighbor
            if r > 0:
                p_top, o_top = grid[r-1][c]
                d = match_bottom_top[p_top][o_top][p][0]
                if d > THRESHOLD:
                    continue

            grid[r][c] = (p, o)
            used.add(p)

            nr, nc = (r, c+1) if c < 2 else (r+1, 0)
            place(nr, nc)

            used.remove(p)
            grid[r][c] = None

place(0, 0)

print("Best score:", best_score)
print("Best solution:", best_solution)

if best_solution:
    print("\nGrid:")
    for row in best_solution:
        print(row)

    print("Distractors:", likely_distractors)
else:
    # Try all subsets if the likely one didn't work
    print("\nLikely subset didn't work. Trying all subsets...")
    piece_subsets = list(combinations(PIECES, 9))
    for subset_idx, subset in enumerate(piece_subsets):
        if subset_idx % 500 == 0:
