print("Best solution:", best_solution)

if best_solution:
    print("\nGrid:")
    for row in best_solution:
        print(row)

    print("Distractors:", likely_distractors)
else:
    # Try all subsets if the likely one didn't work
    print("\nLikely subset didn't work. Trying all subsets...")
    piece_subsets = list(combinations(PIECES, 9))
    for subset_idx, subset in enumerate(piece_subsets):
        if subset_idx % 500 == 0:
            print(f"Processing subset {subset_idx}/5005")

        grid = [[None for _ in range(3)] for _ in range(3)]
        used = set()

