                        p_top, o_top = grid[r-1][c]
                        d = match_bottom_top[p_top][o_top][p][0]
                        if d > THRESHOLD:
                            continue

                    grid[r][c] = (p, o)
                    used.add(p)

                    nr, nc = (r, c+1) if c < 2 else (r+1, 0)
                    place2(nr, nc)

                    used.remove(p)
                    grid[r][c] = None

        place2(0, 0)

        if best_score < 150:
            print("Found good solution, stopping early")
            break

    print("Best score:", best_score)
    print("Best solution:", best_solution)
    if best_solution:
        subset, grid = best_solution
        print("\nGrid:")
        for row in grid:
            print(row)
        distractors = [p for p in PIECES if p not in subset]
        print("Distractors:", distractors)

