    global best_solution, best_score
    if r == 3:
        # Complete grid! Compute total score
        total = 0
        for i in range(3):
            for j in range(3):
                p, o = grid[i][j]
                if j < 2:
                    p2, o2 = grid[i][j+1]
                    d = match_right_left[p][o][p2][0]
                    total += d
                if i < 2:
                    p2, o2 = grid[i+1][j]
                    d = match_bottom_top[p][o][p2][0]
                    total += d
