match_right_left = {}
match_bottom_top = {}

for p1 in PIECES:
    match_right_left[p1] = {}
    match_bottom_top[p1] = {}
    for o1 in range(4):
        match_right_left[p1][o1] = {}
        match_bottom_top[p1][o1] = {}
        _, r1, _, b1 = edges_all[p1][o1]
        for p2 in PIECES:
            if p1 == p2:
                continue
            best_rl = (float('inf'), None)
            best_bt = (float('inf'), None)
