    scores.sort()
    connectivity[p] = np.mean(scores[:8])

print("\nConnectivity scores (lower = better connected):")
for p in sorted(PIECES, key=lambda x: connectivity[x]):
    print(f"  {p}: {connectivity[p]:.2f}")

# The 6 pieces with worst connectivity are likely distractors
